contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We model inputs: from and caddress are arbitrary addresses, _tos is an array, v is uint.
    // The test calls c.transfer and records whether it reverted; if it did not revert we assert it returned true.
    // Additionally we assert that for empty _tos the call must revert (per require in C), and for non-empty
    // the call cannot return false (implementation returns true on success).

    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(true);

        bool reverted = false;
        bool returnedValue = false;
        // Call transfer and capture revert/return
        try c.transfer(from, caddress, _tos, v) returns (bool rv) {
            returnedValue = rv;
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if it returned (did not revert) then it must have returned true.
        // And if _tos.length == 0 then it must revert (require in implementation).
        assert((!reverted && returnedValue) || (_tos.length == 0 && reverted));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Input parameters: from, caddress, _tos, v
    // We assert a general property about return/revert behavior of C.transfer.
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(true);

        bool reverted;
        bool retval;

        // Call transfer and capture whether it reverts and its return value if any.
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            retval = r;
        } catch {
            reverted = true;
            retval = false;
        }

        // General rule:
        // - If _tos.length == 0 then the call must revert (the contract has require(_tos.length > 0)).
        // - If the call did not revert then it must have returned true.
        // Together: either it reverted and _tos.length can be anything, but if it returned then _tos.length>0 and the return value is true.
        assert( reverted || (retval && _tos.length > 0) );
    }

    receive() external payable { }
}

